    id:'C8-B', type:'practice', typeLabel:'實作案例', promptIds:[8],
    title:'案例 B｜專利技術申請書撰寫與競爭分析',
    scene:'誰：研發工程師陳博士｜何時：完成鈦合金複合表面改質技術突破後｜何地：台南某材料研究機構｜什麼事：需要在 2 週內完成發明專利技術申請書，同時規劃申請策略，識別競爭對手可能的迴避設計方向｜為何：機構第一次申請發明專利，不確定申請範圍如何設定才能最大化保護價值｜怎麼做：用頂級分析師框架對技術進行結構化解析，產出申請書初稿與策略建議',
    prep:'用自己的話描述發明內容（製程步驟、關鍵參數、材料）；說明解決的問題（現有技術的缺點）；列出技術突破點和量化實驗結果',
    prompt:`你是一位具備 20 年資歷的智財顧問，同時具備材料工程和製程技術背景，擅長專利技術申請書撰寫和專利布局策略。請用結構化分析思維，協助我完成以下任務。

發明基本資訊：
發明名稱（自訂）：一種提升鈦合金骨科植入物表面生物相容性的複合電化學處理方法
技術說明：
- 發明內容：整合陽極氧化（電壓 30–50V，磷酸電解液）與電漿噴塗（HA 塗層，厚度 20μm），兩段式處理鈦合金表面
- 解決的問題：現有單一技術無法同時達到硬度提升和生物相容性，臨床植入物腐蝕失效率 3.2%
- 技術突破點：整合雙技術一次處理，耐腐蝕性提升 3 倍，骨整合速度縮短 30%
- 實驗結果：表面硬度 HV490（+44%）、鹽霧試驗 720 小時（原 240 小時）、ISO 10993 通過

請完成以下工作：

一、專利技術申請書草稿（技術交底書格式）
- 發明名稱
- 技術領域
- 習知技術說明及缺點
- 發明內容（含較佳實施例）
- 圖式說明建議（描述應繪製的技術示意圖）
- 申請項目建議方向（獨立項 + 附屬項框架）

二、專利申請策略分析（三種策略比較）
表格：| 策略 | 核心思路 | 保護範圍 | 通過難度 | 推薦指數 |
A. 廣度優先：以最廣的方法請求項為主
B. 深度優先：以具體實施例為主
C. 外圍布局：圍繞核心技術申請多件周邊專利

三、競爭對手迴避設計分析
列出 3–5 個對手最可能採取的迴避方向，說明如何預先封堵

四、補強建議
哪些額外實驗數據或實施例，可讓申請書更具說服力

注意：本分析為方向性建議，正式申請需由合格專利師撰寫。
輸出：繁體中文，表格格式`,
