    scene:'誰：業務主任林小姐｜何時：收到德國漢諾威工業展邀請函後｜何地：高雄表面處理廠｜什麼事：首次參加海外展覽，展位 9 平方公尺，預算 NT$80 萬，距展覽剩 4 個月｜為何：拓展歐洲市場，但完全沒有海外參展經驗｜怎麼做：逐步引導完成參展專案規劃',
