    title:'案例 B｜環保專員一個月學會碳足跡盤查',
    scene:'誰：環保專員吳小姐｜何時：公司收到大客戶要求後｜何地：台南金屬製品廠｜什麼事：大客戶要求一個月內提供產品碳足跡報告（ISO 14067 格式），她完全沒有碳盤查經驗｜為何：公司沒有預算請顧問，只能靠自己快速學習｜怎麼做：高效學習模式',
