    scene:'誰：研究員小謝｜何時：台灣材料科學年會前一晚 11 點｜何地：家中書桌前｜什麼事：明天要對 200 位業界人士公開發表研究成果，第一次在這麼大的場合上台｜為何：緊張到睡不著，擔心被問到不會的問題或腦袋空白｜怎麼做：召喚啦啦隊打氣',
