    id:'C5-C', type:'practice', typeLabel:'實作案例', promptIds:[5],
    title:'案例 C｜寵物美容第二家門市展店風險評估',
    scene:'誰：創業者蔡小姐｜何時：第一家門市開業一年後｜何地：台中市｜什麼事：第一家寵物美容店經營穩定，考慮展第二家，有三個地點選項，每個地點各有利弊｜為何：展店涉及 NT$120 萬以上投資，需系統評估風險才能決定｜怎麼做：RPN 風險矩陣 + KSF 分析',
    prep:'整理三個地點的基本資料（租金、商圈、競爭、停車、目標客群），以及你不可接受的最大風險',
    prompt:`你是一位資深策略決策顧問，擅長 RPN 風險管理矩陣與 KSF 分析。

提案主題：寵物美容店第二家門市選址決策（台中市）
決策期限：本月底（房東要求簽意向書）

方案：
A. 勤美商圈店面（月租 NT$6.5 萬，30 坪，人流多，競爭對手已有 2 家在附近）
B. 文心路住宅區店面（月租 NT$3.8 萬，25 坪，社區型，停車方便，無直接競爭）
C. 精明商圈一中街附近（月租 NT$5.2 萬，35 坪，年輕人多，寵物友善餐廳聚集）

目標：展店後 12 個月內達到損益平衡，複製第一家店的 NPS 口碑模式
不可接受風險：開幕 6 個月後月營收低於 NT$20 萬（低於損益平衡點）

RPN 等級：1–4 低 / 5–9 中 / 10–19 高 / 20–25 極高

請完成：決策背景摘要、RPN 風險管理矩陣、風險對策規劃、
KSF 分析、方案總比較矩陣、決策建議`,
    tips:['特別注意「競爭對手已有 2 家在附近」這個風險的 RPN 評分——服務業的競爭地理效應和製造業很不同','追問：「如果選 B 地點，前 3 個月的客源從哪裡來？需要什麼主動行銷手段？」']
