    title:'案例 C｜旅行社數位轉型計畫自我審查',
    scene:'誰：數位轉型主任余先生｜何時：計畫書送公司董事會前一週｜何地：中型旅行社｜什麼事：要向董事會提交「旅行社官網與預訂系統升級計畫」，預算 NT$420 萬，但他自己也不確定 KPI 是否合理、風險是否考慮週全｜為何：董事會成員對數位轉型不熟悉，但對數字很敏感，KPI 和財務效益一定要說得清楚｜怎麼做：10 維度完整健檢',
