    title:'案例 C｜旅行社限定行程快閃海報',
    scene:'誰：行銷企劃余小姐｜何時：快閃行程推出前 3 天｜何地：旅行社台北總部｜什麼事：要快速做一張限定搶位的北陸行程快閃海報，要讓人看到第一眼就有「現在不搶就沒了」的緊迫感，同時傳遞旅遊感和品質感｜為何：快閃海報如果沒有視覺衝擊，放出去 3 分鐘就被其他貼文淹沒｜怎麼做：套用 8+8+8 視覺配方',
