    scene:'誰：產品主任黃小姐｜何時：評估開發「台日跨境旅遊套裝」新產品前｜何地：旅行社台北總部｜什麼事：她做了一些初步研究，但主管說「你這份研究只看到表面，更深的問題你還沒有問到」｜為何：不知道自己不知道什麼，正是新產品開發最危險的狀態｜怎麼做：問題生成器讓 AI 找出她還沒想到的問題',
    prep:'把你目前的研究資料上傳，說明新產品的概念（台日跨境旅遊套裝是什麼）',
